    "optionExplanations": [
      "「お帰りいたしました」的「いたす」是謙讓語，用於自己動作的謙遜表現，不能用來尊敬地描述老師的動作，用法錯誤。",
      "「お帰りにしました」文法形式不正確（「お＋ます形＋にする」是「決定為…」的意思，不是尊敬語），錯誤。",
      "「お帰りされました」在「お＋ます形」尊敬語之外又加上尊敬助動詞「される」，重複冗贅且不自然，錯誤。",
      "「お帰りになりました」是「お＋ます形＋になる」尊敬語句型的正確用法，用來尊敬地描述老師「已經回去了」，為正解。"
    ]
