    "meaning": {
      "prompt": "前の人につづいてまっすぐ＿＿＿＿なさい。",
      "options": [
        "歩いた",
        "歩く",
        "歩き",
        "歩け"
      ],
      "answerIndex": 2
    },
    "optionExplanations": [
      "「歩いた」是過去形，不能接「なさい」，錯誤。",
      "「歩く」是辭書形，不能接「なさい」，錯誤。",
      "「歩きなさい」（走吧），「なさい」要接在動詞ます形（去掉ます）後面，為正解。",
      "「歩け」是命令形，跟「なさい」重複衝突、文法不通，錯誤。"
    ]
