    "meaning": {
      "prompt": "山田さんのアパートは＿＿＿し、広いし、駅からも近い。",
      "options": [
        "きれいな",
        "きれい",
        "きれいだ",
        "きれいの"
      ],
      "answerIndex": 2
    },
    "optionExplanations": [
      "「きれいな」是連體形，不能直接接「し」，錯誤。",
      "「きれい」單獨接「し」不合文法，な形容詞的普通形需要加「だ」，錯誤。",
      "「きれいだし」（既漂亮），な形容詞的普通形「きれいだ」加上表列舉理由的「し」，為正解。",
      "「きれいの」不是正確的日文形式，錯誤。"
    ]
