    "meaning": {
      "prompt": "あの人は３０分ずっと＿＿＿つづけている。",
      "options": [
        "話し",
        "話そう",
        "話す",
        "話さ"
      ],
      "answerIndex": 0
    },
    "optionExplanations": [
      "「話しつづけている」（一直持續在說），「つづける」要接在動詞ます形（去掉ます）後面，為正解。",
      "「話そう」是意向形，不能接「つづける」，錯誤。",
      "「話す」是辭書形，不能直接接「つづける」，錯誤。",
      "「話さ」是未然形，不能直接接「つづける」，錯誤。"
    ]
