    "notes": [
      {
        "surface": "ことがあります",
        "word": "〜ことがある",
        "reading": "",
        "meaning": "（動詞辭書形＋ことがある）有時候會做…",
        "type": "grammar"
      }
    ],
    "optionExplanations": [
      "「歌うの」文法不通，「ことがある」前面不需要加「の」，錯誤。",
      "「歌い」是ます形，不能直接接「ことがある」，錯誤。",
      "「歌うことがあります」（有時候會唱日本歌），「ことがある」要接在動詞辭書形後面，為正解。",
      "「歌います」是丁寧形，不能直接接「ことがある」，錯誤。"
    ]
