    "meaning": {
      "prompt": "あ、お金が＿＿＿＿。",
      "options": [
        "おちています",
        "おちてあります",
        "おとしています",
        "おとしてあります"
      ],
      "answerIndex": 0
    },
    "optionExplanations": [
      "「おちています」（（錢）掉在地上），「落ちる」是自動詞，「〜ている」表示掉落後目前的狀態，為正解。",
      "「おちてあります」文法不通，自動詞不能接「〜てある」，錯誤。",
      "「おとしています」文法上可以成立，但「落とす」是他動詞（使掉落），暗示是某人正在做「使掉落」的動作，跟「發現錢掉在地上」的語意不符，錯誤。",
      "「おとしてあります」文法不通，「〜てある」通常接他動詞表示人為造成的狀態殘留，但本句沒有人為刻意弄掉錢的語境，錯誤。"
    ]
