    "meaning": {
      "prompt": "学校をそつぎょうしても、日本語の勉強をつづけて＿＿＿＿つもりだ。",
      "options": [
        "くる",
        "いく",
        "いこう",
        "こよう"
      ],
      "answerIndex": 1
    },
    "optionExplanations": [
      "「続けてくるつもり」語意不符，「〜てくる」表示從過去持續到現在，跟本句「畢業後仍要繼續」朝向未來的語意不符，錯誤。",
      "「続けていくつもりだ」（打算繼續學下去），「〜ていく」表示動作從現在朝未來持續，加上「つもりだ」表打算，為正解。",
      "「いこう」是意向形，不能直接接「つもりだ」，錯誤。",
      "「こよう」是「くる」的意向形，不能直接接「つもりだ」，錯誤。"
    ]
