    "meaning": {
      "prompt": "学生＿＿＿もっと勉強しなさい。",
      "options": [
        "みたい",
        "みたいな",
        "らしく",
        "らしい"
      ],
      "answerIndex": 2
    },
    "optionExplanations": [
      "「みたい」不能直接修飾後面的動詞「勉強しなさい」，文法不符，錯誤。",
      "「みたいな」是連體形，不能修飾動詞，錯誤。",
      "「学生らしく勉強しなさい」（要有學生的樣子好好唸書），「らしく」是「らしい」的副詞形，用來修飾動詞，為正解。",
      "「らしい」是終止形／連體形，不能直接修飾後面的動詞，錯誤。"
    ]
