    "meaning": {
      "prompt": "小林さんが＿＿＿＿、かならず私に知らせて下さい。",
      "options": [
        "来たら",
        "来ると",
        "来たり",
        "来るまま"
      ],
      "answerIndex": 0
    },
    "optionExplanations": [
      "「小林さんが来たら、知らせてください」（小林先生來了的話請告訴我），「たら」表示條件，後面接請求句「〜てください」，為正解。",
      "「来ると」的「と」後面通常不能接命令、請求句，文法不符，錯誤。",
      "「来たり」是列舉用法「〜たり〜たり」，不能單獨這樣使用，錯誤。",
      "「来るまま」文法不通，「まま」通常接在た形後面表示「保持…的狀態」，不能這樣接辭書形，錯誤。"
    ]
